/* Editable interaction prototype. All data and command results are simulated locally. */
(() => {
'use strict';
const app=document.querySelector('#app');
const palette=[['Đỏ','#EF4444'],['Xanh lá','#22C55E'],['Xanh dương','#3B82F6'],['Vàng','#EAB308'],['Trắng','#FFFFFF']];
const metrics={humidity:{label:'Độ ẩm',unit:'%',color:'#111111',values:[61,62,64,66,65,64,65]},temperature:{label:'Nhiệt độ',unit:'°C',color:'#111111',values:[26.8,27,27.1,27.4,27.7,27.6,27.5]},co2:{label:'CO₂ ước lượng',unit:'ppm',color:'#111111',values:[720,750,810,840,870,860,850]}};
const dateLabels=['02/11 14:30','02/11 18:30','02/11 22:30','03/11 02:30','03/11 06:30','03/11 10:30','03/11 14:30'];
const daily={humidity:[64,63,65,67,66,64,64.5],temperature:[26.8,27,27.1,27.4,27.7,27.6,27.5],co2:[720,750,810,840,870,860,850]};
const heatValues=[[62,61,63,65,64,62,63],[63,62,64,66,65,63,64],[64,63,65,67,66,64,65],[65,64,66,68,67,65,64.5],[66,65,67,69,68,66,null],[64,63,65,67,66,64,null]];
const s={brightness:70,appliedBrightness:70,hue:45,saturation:95,colorValue:92,user:'demo_user',route:'overview',account:false,on:true,applied:'#3B82F6',draft:'#EAB308',hex:'#EAB308',hexError:'',advanced:false,pending:false,feedback:null,online:true,failNext:false,metric:'humidity',range:'24h',mode:'hour',appliedRange:'24h',from:'2026-11-02',to:'2026-11-03',dateError:'',dirty:false,historyState:'ready',point:6,cell:[3,6],authMessage:'',session:0};
const users=new Map([['demo_user','smartclassroom16']]);
let accountOpener='account';
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=1)=>Number(n).toLocaleString('vi-VN',{maximumFractionDigits:d});
const name=hex=>palette.find(c=>c[1]===hex)?.[0]??'Tùy chỉnh';
const title=()=>routeTitle();
const icon=n=>`<span class="nav-icon" aria-hidden="true"><svg viewBox="0 0 24 24">${n==='overview'?'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>':n==='led'?'<path d="M9 18h6m-6 3h6M8 13a6 6 0 1 1 8 0l-1 3H9z"/>':'<path d="M3 3v18h18M5 15l5-7 5 4 6-7"/>'}</svg></span>`;
const nav=(mobile=false)=>`<nav class="${mobile?'bottom-nav':'desktop-nav'}" aria-label="${mobile?'Các tab chính':'Điều hướng chính'}">${(mobile?[['overview','Giám sát'],['led','Đèn LED'],['history','Lịch sử']]:[['overview','Tổng quan'],['history','Lịch sử'],['led','Đèn LED'],['sensor','Cảm biến']]).map(([r,t],i)=>`<button type="button" data-route="${r}" ${section(s.route)===r?'aria-current="page"':''}>${mobile?icon(r):'<span class="nav-index" aria-hidden="true">0'+(i+1)+'</span>'}<span>${t}</span></button>`).join('')}</nav>`;
const badge=()=>`<span class="badge ${s.online?'':'stale'}"><span class="live-dot"></span>${s.online?'Cập nhật 5 giây trước':'Dữ liệu cũ · lần nhận cuối 14:30'}</span>`;
const feedback=()=>s.feedback?`<div class="feedback ${s.feedback.type}" role="status">${esc(s.feedback.text)}</div>`:'';
const announce=t=>{document.querySelector('#announcer').textContent=t;};
function navigate(route){if(s.pending)return;s.account=false;s.route=s.user||route==='wifi'?route:'login';s.feedback=null;location.hash=s.route;render();document.querySelector('#main')?.focus();window.scrollTo(0,0);}
function spark(metric){const a=metrics[metric],v=a.values,min=Math.min(...v),max=Math.max(...v);return `<svg class="spark" viewBox="0 0 300 44" aria-hidden="true"><polyline points="${v.map((x,i)=>`${i*50},${38-(x-min)/(max-min||1)*30}`).join(' ')}" fill="none" stroke="${a.color}" stroke-width="3"/></svg>`;}
function humidityGauge(){return '<div class="humidity-gauge" role="meter" aria-label="Độ ẩm phòng'+(!s.online?' · dữ liệu cũ':'')+'" aria-valuemin="0" aria-valuemax="100" aria-valuenow="65"><svg viewBox="0 0 180 140" aria-hidden="true"><path class="gauge-rail" d="M16 88 A74 74 0 0 1 164 88" pathLength="100"/><path class="gauge-fill" d="M16 88 A74 74 0 0 1 164 88" pathLength="100" stroke-dasharray="65 100"/><text class="gauge-number" x="90" y="84" text-anchor="middle">65<tspan font-size="24">%</tspan></text><text class="gauge-end" x="16" y="116">0</text><text class="gauge-end" x="164" y="116" text-anchor="end">100%</text></svg></div>';}
function metricCards(){return '<div class="grid metrics">'+Object.entries(metrics).map(([k,m])=>k==='humidity'?'<section class="card metric humidity dark"><div class="humidity-copy"><h2>Độ ẩm phòng</h2><span class="mini-state">'+(s.online?'Đang nhận':'Dữ liệu cũ')+'</span><p class="gauge-caption">Thang đo<br>0–100%</p></div>'+humidityGauge()+'<p class="humidity-change">'+(s.online?'Tăng 4 điểm phần trăm / 24 giờ':'Lần nhận cuối · 14:30')+'</p></section>':'<section class="card metric '+k+'"><h2>'+m.label+(!s.online?' · lần nhận cuối':'')+'</h2><p class="value">'+fmt(m.values[6])+'<span class="unit">'+m.unit+'</span></p>'+(s.online?spark(k):'')+'<p class="muted">'+(!s.online?'14:30 · Dữ liệu cũ':k==='temperature'?'26,8–27,7°C trong 24 giờ':'Ước lượng · Tham khảo')+'</p></section>').join('')+'</div>';}

function series(){const day=s.mode==='day',keys=day?['2026-10-28','2026-10-29','2026-10-30','2026-10-31','2026-11-01','2026-11-02','2026-11-03']:['2026-11-02','2026-11-02','2026-11-02','2026-11-03','2026-11-03','2026-11-03','2026-11-03'],labels=day?['28/10','29/10','30/10','31/10','01/11','02/11','03/11']:dateLabels,values=day?daily[s.metric]:metrics[s.metric].values;return values.map((value,i)=>({value,label:labels[i],date:keys[i]})).filter(r=>s.route==='overview'||(s.appliedRange==='custom'?r.date>=s.appliedFrom&&r.date<=s.appliedTo:s.appliedRange==='24h'?r.date>='2026-11-02':true));}
function lastColor(){return '<div class="last-color"><span class="swatch" style="--color:'+s.applied+'" aria-hidden="true"></span><div><p class="small muted">Màu đã gửi gần nhất</p><strong>'+name(s.applied)+'</strong><p class="small muted" id="applied-brightness">Độ sáng '+s.appliedBrightness+'% · Chưa xác nhận đèn thực tế</p></div></div>';}
function overview(){return `${!s.online?stale():''}${metricCards()}<div class="grid dashboard-bottom"><section class="card"><div class="row"><h2>Nhịp thay đổi độ ẩm</h2><button data-route="history">Lịch sử →</button></div><p class="muted small">24 giờ qua · 02/11 14:30 → 03/11 14:30</p>${overviewChart()}</section><section class="card led-summary"><h2>Ánh sáng theo ý bạn</h2><p class="badge">Yêu cầu: ${s.on?'Bật':'Tắt'}</p>${lastColor()}<p class="muted small">Chọn màu có tên, xem trước rồi áp dụng.</p><button class="primary" data-route="led">Điều khiển LED →</button></section></div><section class="card week-card"><h2>Độ ẩm trung bình theo ngày (%)</h2><p class="muted small">28/10–03/11 · Hôm nay chưa kết thúc</p>${bars()}<button data-route="daily">Xem phân tích theo ngày →</button></section>${featureHub()}`;}

function stale(){return `<div class="stale-banner"><strong>Thiết bị chưa có bản tin mới</strong><p>Kiểm tra nguồn và WiFi thiết bị. Bạn vẫn xem được lịch sử đã lưu. Điều khiển LED tạm khóa.</p></div>`;}
function led(){const disabled=!s.online||!s.on||s.pending;return (!s.online?stale():'')+'<div class="grid led-layout"><section class="card power-card"><div><div class="row"><h2 class="power-title">Đèn của phòng</h2><button id="power" class="switch" role="switch" aria-checked="'+s.on+'" aria-label="Bật / Tắt đèn" '+(!s.online||s.pending?'disabled':'')+'></button></div><p class="small muted" style="margin-top:12px">Bật / tắt gửi lệnh ngay.</p></div><div class="led-strip" aria-hidden="true" style="--color:'+s.applied+';--level:'+(s.appliedBrightness/100)+'">'+Array(8).fill('<i></i>').join('')+'</div>'+lastColor()+'<hr class="divider"><p class="power-explainer muted">Đã gửi lệnh tới hệ thống.<br>Chưa xác nhận đèn thực tế.</p><p class="power-explainer muted">Tắt đèn sẽ khóa phần chọn màu và độ sáng.</p></section><section class="card color-editor"><h2 class="step-title">01 <span>Chọn màu bạn thích</span></h2><p class="muted choose-help">Chạm vào ô màu. Dấu ✓ cho biết màu đang chọn.</p><div class="palette" role="group" aria-label="Màu có sẵn">'+palette.map(([n,h],i)=>'<button id="color-'+i+'" class="color-choice" style="--color:'+h+'" data-color="'+h+'" aria-pressed="'+(s.draft===h)+'" '+(disabled?'disabled':'')+'><span class="color-block" aria-hidden="true"></span><span class="check" aria-hidden="true">✓</span><span>'+n+'</span></button>').join('')+'</div><div class="brightness-editor"><div class="row"><label for="brightness">Độ sáng</label><output id="brightness-value" for="brightness">'+s.brightness+'%</output></div><input type="range" id="brightness" style="--progress:'+((s.brightness-1)/99*100)+'%" min="1" max="100" step="1" value="'+s.brightness+'" aria-label="Độ sáng LED" aria-valuetext="'+s.brightness+' phần trăm" '+(disabled?'disabled':'')+'><div class="range-ends"><span>1% · Thấp</span><span>100% · Cao</span></div></div><div class="draft-card"><span class="swatch" data-draft-color style="--color:'+s.draft+'" aria-hidden="true"></span><div><p>02 · Xem trước</p><h3>Màu đang chọn: '+name(s.draft)+'</h3><p id="draft-level">Độ sáng '+s.brightness+'%</p><p class="pending" id="draft-pending">'+(s.pending?'Đang gửi lệnh…':!hasChange()?'Trùng yêu cầu đã gửi gần nhất':'Chưa gửi · Đèn chưa đổi màu')+'</p></div></div>'+feedback()+'<button id="apply" class="primary apply" '+(!canApply()?'disabled':'')+'>'+(s.pending?'Đang gửi…':'Áp dụng màu '+(name(s.draft)==='Tùy chỉnh'?'này':name(s.draft))+' →')+'</button><p class="apply-help">'+(!s.on?'Bật đèn để chọn màu.':'Màu và độ sáng được gửi cùng nhau khi bạn áp dụng.')+'</p><details class="advanced" '+(s.advanced?'open':'')+'><summary>Màu tùy chỉnh · Chọn theo ý bạn</summary><p class="small muted">Chọn sắc màu, chạm vào ô để tìm sắc độ. Bạn cũng có thể nhập mã HEX.</p><div id="sv-picker" class="sv-picker" style="--hue:'+s.hue+'" tabindex="'+(disabled?'-1':'0')+'" role="group" aria-disabled="'+disabled+'" aria-label="Chọn sắc độ. Phím trái phải chỉnh độ đậm; lên xuống chỉnh độ sáng của màu."><span id="sv-handle" style="left:'+s.saturation+'%;top:'+(100-s.colorValue)+'%" aria-hidden="true"></span></div><div class="hue-control"><label for="hue">Đổi sắc màu</label><input type="range" id="hue" min="0" max="359" step="1" value="'+Math.round(s.hue)+'" aria-label="Sắc màu" aria-valuetext="'+Math.round(s.hue)+' độ" '+(disabled?'disabled':'')+'></div><div class="hex-field"><label for="hex">Mã HEX · tùy chọn</label><div class="hex-control"><input id="hex" value="'+esc(s.hex)+'" autocomplete="off" spellcheck="false" maxlength="7" aria-invalid="'+!!s.hexError+'" aria-describedby="hex-help hex-error" '+(disabled?'disabled':'')+'><button id="hex-preview" '+(disabled?'disabled':'')+'>Xem trước</button></div><small id="hex-help" class="muted">Mã gồm # và 6 ký tự. Ví dụ: #EAB308.</small><p id="hex-error" class="input-error" role="alert">'+esc(s.hexError)+'</p></div><button id="hex-cancel" '+(s.pending?'disabled':'')+'>Hủy thay đổi đang chọn</button></details></section></div>';}
function selectedData(){return series().map(r=>r.value);}
function stats(){const v=selectedData(),m=metrics[s.metric],mean=v.reduce((a,b)=>a+b,0)/v.length;return `<section class="card"><h2>Thống kê khoảng đang chọn</h2><div class="stats-list"><div class="stat-large"><span>Trung bình ${s.mode==='day'?'ngày':'mẫu'}</span><strong>${fmt(mean)} ${m.unit}</strong></div><div class="stat-pair"><span>Thấp nhất <strong>${fmt(Math.min(...v))} ${m.unit}</strong></span><span>Cao nhất <strong>${fmt(Math.max(...v))} ${m.unit}</strong></span></div></div><p class="muted small" style="margin-top:20px">${v.length} ${s.mode==='day'?'ngày':'mẫu'} minh họa trong khoảng đang xem.</p></section>`;}

function heatReadout(){const [r,c]=s.cell,v=heatValues[r][c];return `${['28/10','29/10','30/10','31/10','01/11','02/11','03/11'][c]} ${r*4}:00 · ${v===null?'Chưa có dữ liệu':`Độ ẩm: <strong>${fmt(v)}%</strong>`}`;}
function history(){return `<section class="card filters" aria-label="Bộ lọc lịch sử"><div class="field"><label for="metric">Chỉ số</label><select id="metric">${Object.entries(metrics).map(([k,m])=>`<option value="${k}" ${s.metric===k?'selected':''}>${m.label}</option>`).join('')}</select></div><div class="field"><label for="range">Khoảng thời gian</label><select id="range">${[['24h','24 giờ qua'],['7d','7 ngày qua'],['custom','Tùy chọn']].map(([v,t])=>`<option value="${v}" ${s.range===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="field mode-field"><label>Chế độ xem</label><div class="segmented" role="group" aria-label="Chế độ xem">${[['hour','Theo giờ'],['day','Theo ngày']].map(([v,t])=>`<button data-mode="${v}" aria-pressed="${s.mode===v}">${t}</button>`).join('')}</div></div>${s.range==='custom'?`<div class="custom-dates"><div class="field"><label for="from">Từ ngày</label><input type="date" id="from" value="${s.from}" aria-describedby="date-error" aria-invalid="${!!s.dateError}"></div><div class="field"><label for="to">Đến ngày</label><input type="date" id="to" value="${s.to}" aria-describedby="date-error" aria-invalid="${!!s.dateError}"></div><button id="apply-dates" class="primary">Xem lịch sử</button><p class="input-error" id="date-error" role="alert">${esc(s.dateError)}</p></div>`:''}<p class="filter-caption">${s.dirty?'Chưa áp dụng ngày mới. Biểu đồ giữ khoảng đã áp dụng.':'Bộ lọc tự cập nhật. Ngày tùy chọn cần nhấn Xem lịch sử.'}</p></section>${s.historyState==='loading'?'<section class="card empty" role="status"><h2>Đang tải lịch sử…</h2><p>Đang cập nhật theo bộ lọc mới.</p></section>':s.historyState==='empty'?'<section class="card empty"><h2>Chưa có dữ liệu trong khoảng này</h2><p>Thử chọn khoảng ngày khác hoặc chờ thiết bị gửi dữ liệu.</p><button id="reset-range">Xem 24 giờ minh họa</button></section>':s.historyState==='error'?'<section class="card empty"><h2>Không tải được lịch sử</h2><p>Kiểm tra kết nối và thử lại.</p><button id="retry-history">Thử lại</button></section>':`<div class="history-shortcuts"><button data-route="records">Bản ghi cảm biến →</button><button data-route="daily">Phân tích theo ngày →</button><button data-route="filters">Bộ lọc thời gian →</button></div><div class="grid history-layout"><section class="card"><h2>${metrics[s.metric].label} theo thời gian</h2><p class="muted small">Khoảng đã áp dụng: ${rangeText()} · Dữ liệu minh họa</p>${chart()}</section>${stats()}</div>${s.metric==='humidity'?heatmap():''}`}`;}
function rangeText(){return s.appliedRange==='custom'?`${s.appliedFrom} → ${s.appliedTo}`:s.appliedRange==='7d'?'28/10–03/11/2026':'02/11/2026 14:30 → 03/11/2026 14:30';}
function sensor(){return `<div class="subpage-actions"><button data-route="overview">← Giám sát</button><button data-route="temperature">Nhiệt độ →</button><button data-route="co2">CO₂ ước lượng →</button></div><div style="margin-top:20px">${metricCards()}</div><section class="card"><h2>3 bản ghi mới nhất</h2><div class="table-wrap"><table><caption class="sr-only">Dữ liệu cảm biến minh họa</caption><thead><tr><th>Thời điểm</th><th>Độ ẩm (%)</th><th>Nhiệt độ (°C)</th><th>CO₂ ước lượng (ppm)</th></tr></thead><tbody>${[6,5,4].map(i=>`<tr><td>${dateLabels[i]}</td><td>${metrics.humidity.values[i]}</td><td>${fmt(metrics.temperature.values[i])}</td><td>${metrics.co2.values[i]}</td></tr>`).join('')}</tbody></table></div></section>`;}
function tools(){return `<details class="prototype-tools"><summary>Bản thử tương tác · Dữ liệu minh họa · Thử tình huống</summary><div class="controls"><button id="test-online">${s.online?'Mô phỏng mất kết nối':'Khôi phục kết nối'}</button><button id="test-fail">${s.failNext?'Lệnh tiếp theo sẽ lỗi':'Mô phỏng lỗi lệnh tiếp theo'}</button><button data-history-state="empty">Lịch sử rỗng</button><button data-history-state="error">Lỗi lịch sử</button><button id="test-expire">Hết phiên</button><button data-route="wifi">Cấu hình WiFi</button></div><p>Chỉ mô phỏng giao diện trên máy. Không kết nối ESP32, MQTT hoặc lưu mật khẩu ra tệp.</p></details>`;}
function account(){return `<div class="dialog-backdrop" id="account-backdrop"><section class="card dialog" role="dialog" aria-modal="true" aria-labelledby="account-title"><h2 id="account-title">Tài khoản</h2><div class="identity"><span class="avatar">DU</span><strong>${esc(s.user)}</strong></div><p class="muted small">Một tài khoản cho web và điện thoại.</p><button data-route="profile">Xem tài khoản →</button><button data-route="device">Thiết bị & kết nối →</button><button data-route="telegram">Telegram →</button><button id="account-close">Đóng</button><button id="logout" class="danger">Đăng xuất</button></section></div>`;}
function auth(){const reg=s.route==='register';return `<main class="auth-shell" id="main" tabindex="-1"><aside class="auth-hero"><p class="auth-wordmark">SMART CLASSROOM</p><h2>Hiểu căn phòng.<br>Học tập tốt hơn.</h2><p>Dữ liệu môi trường rõ ràng.<br>Điều khiển trong tầm tay.</p><div class="auth-graphic"><span>65<small>%</small></span><p>Độ ẩm phòng học</p></div><div class="auth-footnote">Độ ẩm / Không khí / Ánh sáng</div></aside><section class="card auth-card"><div class="brand"><span class="brand-mark">▦</span>Phòng học thông minh</div><h1>${reg?'Tạo tài khoản':'Đăng nhập'}</h1><p class="muted">${reg?'Một tài khoản cho web và điện thoại.':'Theo dõi dữ liệu và điều khiển thiết bị.'}</p>${s.authMessage?`<div class="feedback info" role="status">${esc(s.authMessage)}</div>`:''}<form id="auth-form" novalidate><div class="field"><label for="username">Tài khoản</label><input id="username" autocomplete="username" required value="${esc(s.newUser??'')}" aria-describedby="auth-error"></div><div class="field"><label for="password">Mật khẩu</label><div class="password-field"><input type="password" id="password" autocomplete="${reg?'new-password':'current-password'}" required aria-describedby="auth-error"><button type="button" id="show-password" aria-pressed="false">Hiện</button></div></div>${reg?'<div class="field"><label for="confirm">Xác nhận mật khẩu</label><input id="confirm" type="password" autocomplete="new-password" required aria-describedby="auth-error"><small class="muted">Mật khẩu tối thiểu 8 ký tự.</small></div>':''}<p id="auth-error" class="input-error" role="alert"></p><button id="auth-submit" class="primary" type="submit">${reg?'Tạo tài khoản':'Đăng nhập'}</button></form><p class="auth-switch">${reg?'Đã có tài khoản?':'Chưa có tài khoản?'} <button class="link-button" id="auth-switch">${reg?'Đăng nhập':'Tạo tài khoản'}</button></p>${!reg?'<button id="demo-login">Dùng tài khoản mẫu</button>':''}<p class="muted small" style="margin-top:20px">Bản thử tương tác · Tài khoản chỉ tồn tại trong phiên mở trang.</p></section></main>`;}
function wifi(){return `<section class="card wifi-steps"><h2>Kết nối WiFi cho thiết bị</h2><p class="muted">Chọn mạng thường dùng để thiết bị gửi dữ liệu lên hệ thống.</p><form id="wifi-form"><div class="field"><label for="ssid">Mạng WiFi</label><select id="ssid"><option>Classroom-WiFi</option><option>HCMUS-Lab</option></select></div><div class="field"><label for="wifi-pass">Mật khẩu WiFi</label><input id="wifi-pass" type="password" required autocomplete="off"></div><button class="primary" type="submit">Lưu và kết nối →</button><p id="wifi-result" role="status" style="margin-top:20px"></p></form><p class="muted small">Sau khi lưu, thiết bị sẽ khởi động lại. Trở về mạng thường dùng rồi kiểm tra dữ liệu trên trang Giám sát.</p></section>`;}
function render(focusId){const keep=focusId??document.activeElement?.id;if(s.route==='wifi'){app.innerHTML=`<main class="auth-shell" id="main" tabindex="-1"><div>${wifi()}<button data-route="overview" style="margin-top:16px">← Về trang giám sát / đăng nhập</button></div></main>`;bind();return;}if(!s.user||['login','register'].includes(s.route)){app.innerHTML=auth();bind();return;}
app.innerHTML=`<div class="shell"><div class="workspace"><header class="masthead"><div class="topbar"><a class="desktop-brand" href="#overview" aria-label="Smart Classroom — Tổng quan"><span class="brand-monogram" aria-hidden="true">S/C</span><span><strong>Smart Classroom</strong><small>PHÒNG HỌC THÔNG MINH</small></span></a><h1>${title()}</h1><div class="header-actions">${badge()}<button class="account-toggle" id="account" aria-label="Mở menu tài khoản" aria-haspopup="dialog"><span class="account-initials">DU</span><span class="account-name">${esc(s.user)} <span aria-hidden="true">⌄</span></span></button></div></div>${nav()}</header><main id="main" tabindex="-1" class="content"><div class="page-intro"><h1>${s.route==='overview'?'Tổng quan phòng học':title()}</h1><p class="muted">${({overview:'Dữ liệu mới nhất, để bạn chủ động hơn mỗi ngày.',led:'Chọn màu. Chỉnh độ sáng. Xem trước rồi áp dụng.',history:'Đọc xu hướng, đối chiếu theo ngày và tìm đúng thời điểm.',sensor:'Giá trị hiện tại và từng điểm dữ liệu.'})[s.route]??''}</p></div><div class="mobile-fresh">${badge()}</div>${pageForRoute()}${tools()}</main>${nav(true)}</div></div>${s.account?account():''}`;bind();if(keep)document.getElementById(keep)?.focus({preventScroll:true});}
async function send(kind){if(s.pending||!s.online||(kind==='color'&&!canApply()))return;const before=s.on,color=s.draft,level=s.brightness,session=s.session,fail=s.failNext;s.pending=true;s.failNext=false;s.feedback={type:'info',text:kind==='power'?'Đang gửi yêu cầu bật / tắt…':'Đang gửi màu '+name(color)+' · '+level+'%…'};render();announce(s.feedback.text);await new Promise(r=>setTimeout(r,650));if(session!==s.session)return;s.pending=false;if(!s.online||fail){s.on=before;s.feedback={type:'error',text:'Không gửi được lệnh. Màu và độ sáng đang chọn vẫn được giữ; kiểm tra kết nối rồi thử lại.'};}else{if(kind==='power')s.on=!before;else{s.applied=color;s.appliedBrightness=level;}s.feedback={type:'success',text:'Đã gửi lệnh '+(kind==='power'?(s.on?'bật':'tắt')+' đèn':'màu '+name(color)+' · độ sáng '+level+'%')+'. Chưa xác nhận phần cứng đã thực hiện.'};}render();announce(s.feedback.text);}
let querySerial=0;
async function loadHistory(){const serial=++querySerial;s.historyState='loading';render();await new Promise(r=>setTimeout(r,400));if(serial!==querySerial)return;s.historyState=series().length?'ready':'empty';render();}
function logout(expired=false){s.session++;s.pending=false;s.user=null;s.account=false;s.route='login';s.authMessage=expired?'Phiên đã hết. Vui lòng đăng nhập lại.':'';s.newUser='';s.feedback=null;location.hash='login';render();}
function hasChange(){return s.draft!==s.applied||s.brightness!==s.appliedBrightness;}
function canApply(){return !s.pending&&s.online&&s.on&&!s.hexError&&!(s.advanced&&s.hex.trim().toUpperCase()!==s.draft)&&hasChange();}
function hexToHsv(hex){const a=hex.slice(1).match(/../g).map(x=>parseInt(x,16)/255),max=Math.max(...a),min=Math.min(...a),delta=max-min;let h=0;if(delta){if(max===a[0])h=((a[1]-a[2])/delta)%6;else if(max===a[1])h=(a[2]-a[0])/delta+2;else h=(a[0]-a[1])/delta+4;}return {h:(h*60+360)%360,s:max?delta/max*100:0,v:max*100};}
function hsvToHex(h,sat,v){const ss=sat/100,vv=v/100,c=vv*ss,x=c*(1-Math.abs((h/60)%2-1)),m=vv-c,a=h<60?[c,x,0]:h<120?[x,c,0]:h<180?[0,c,x]:h<240?[0,x,c]:h<300?[x,0,c]:[c,0,x];return '#'+a.map(n=>Math.round((n+m)*255).toString(16).padStart(2,'0')).join('').toUpperCase();}
function choose(hex,id){if(!s.on||!s.online||s.pending)return;s.draft=hex;s.hex=hex;s.hexError='';const hsv=hexToHsv(hex);s.hue=hsv.h;s.saturation=hsv.s;s.colorValue=hsv.v;s.feedback=null;render(id);announce('Đang chọn '+name(hex)+'. Chưa gửi tới đèn.');}
function refreshDraft(){document.querySelectorAll('[data-draft-color]').forEach(e=>e.style.setProperty('--color',s.draft));document.querySelectorAll('[data-color]').forEach(e=>e.setAttribute('aria-pressed',e.dataset.color===s.draft));const a=document.querySelector('#apply');if(a){a.disabled=!canApply();a.textContent='Áp dụng màu '+(name(s.draft)==='Tùy chỉnh'?'này':name(s.draft))+' →';}const h=document.querySelector('.draft-card h3');if(h)h.textContent='Màu đang chọn: '+name(s.draft);const level=document.querySelector('#draft-level');if(level)level.textContent='Độ sáng '+s.brightness+'%';const pending=document.querySelector('#draft-pending');if(pending)pending.textContent=hasChange()?'Chưa gửi · Đèn chưa đổi màu':'Trùng yêu cầu đã gửi gần nhất';const output=document.querySelector('#brightness-value');if(output)output.textContent=s.brightness+'%';document.querySelector('#brightness')?.style.setProperty('--progress',((s.brightness-1)/99*100)+'%');document.querySelector('#brightness')?.setAttribute('aria-valuetext',s.brightness+' phần trăm');document.querySelectorAll('.feedback').forEach(e=>e.remove());s.feedback=null;}
function updateCustomColor(){s.draft=hsvToHex(s.hue,s.saturation,s.colorValue);s.hex=s.draft;s.hexError='';const hex=document.querySelector('#hex');if(hex){hex.value=s.hex;hex.setAttribute('aria-invalid','false');}const error=document.querySelector('#hex-error');if(error)error.textContent='';const sv=document.querySelector('#sv-picker');if(sv)sv.style.setProperty('--hue',s.hue);const handle=document.querySelector('#sv-handle');if(handle){handle.style.left=s.saturation+'%';handle.style.top=(100-s.colorValue)+'%';}refreshDraft();}
function bindColorControls(){const brightness=document.querySelector('#brightness');brightness?.addEventListener('input',e=>{s.brightness=Math.max(1,Math.min(100,+e.target.value));refreshDraft();});const hue=document.querySelector('#hue');hue?.addEventListener('input',e=>{s.hue=+e.target.value;if(s.saturation===0){s.saturation=85;s.colorValue=95;}hue.setAttribute('aria-valuetext',s.hue+' độ');updateCustomColor();});const picker=document.querySelector('#sv-picker');if(!picker)return;const allowed=()=>s.online&&s.on&&!s.pending;const setFromPoint=e=>{if(!allowed())return;const r=picker.getBoundingClientRect();s.saturation=Math.max(0,Math.min(100,(e.clientX-r.left)/r.width*100));s.colorValue=100-Math.max(0,Math.min(100,(e.clientY-r.top)/r.height*100));updateCustomColor();};picker.addEventListener('pointerdown',e=>{if(!allowed())return;picker.setPointerCapture(e.pointerId);picker.focus();setFromPoint(e);});picker.addEventListener('pointermove',e=>{if(picker.hasPointerCapture(e.pointerId))setFromPoint(e);});picker.addEventListener('keydown',e=>{if(!allowed()||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const step=e.shiftKey?10:1;if(e.key==='ArrowLeft')s.saturation=Math.max(0,s.saturation-step);if(e.key==='ArrowRight')s.saturation=Math.min(100,s.saturation+step);if(e.key==='ArrowUp')s.colorValue=Math.min(100,s.colorValue+step);if(e.key==='ArrowDown')s.colorValue=Math.max(0,s.colorValue-step);updateCustomColor();announce('Màu đang chọn '+s.draft);});}
function sampleRows(metric='humidity',mode='hour'){
 const values=mode==='day'?daily[metric]:metrics[metric].values;
 return values.map((value,i)=>({value,date:mode==='day'?['2026-10-28','2026-10-29','2026-10-30','2026-10-31','2026-11-01','2026-11-02','2026-11-03'][i]:i<3?'2026-11-02':'2026-11-03',label:mode==='day'?['28/10','29/10','30/10','31/10','01/11','02/11','03/11'][i]:dateLabels[i]}));
}

function chartSpec(view='current'){
 let metric=s.metric,mode=s.mode,rows=series();
 if(view==='overview'||['temperature','co2'].includes(view)){metric=view==='overview'?'humidity':view;mode='hour';rows=sampleRows(metric);}
 if(view==='daily'){mode='day';rows=sampleRows(metric,'day');}
 if(view==='daydetail'){metric='humidity';mode='hour';rows=[63,64,65,64.5,null,null].map((value,i)=>({value,date:'2026-11-03',label:'03/11 '+String(i*4).padStart(2,'0')+':00'}));}
 return {metric,mode,rows:rows.map(r=>({...r,time:r.label.match(/\d{2}:\d{2}/)?.[0]??'00:00',stamp:Date.parse(r.date+'T'+(r.label.match(/\d{2}:\d{2}/)?.[0]??'00:00')+':00+07:00')})),view};
}

function chartSvg(spec,mobile=false){
 const {metric,mode,rows,view}=spec,m=metrics[metric],valid=rows.filter(r=>r.value!==null),W=mobile?320:720;
 if(mode==='day'&&mobile)return dailyHorizontalSvg(rows,metric);
 const H=300,L=mobile?44:54,R=W-(mobile?24:28),T=44,B=196,domain=mode==='day'?(metric==='humidity'?[0,100]:metric==='temperature'?[0,30]:[0,1000]):metric==='humidity'?[55,70]:metric==='temperature'?[26,28]:[600,900],ticks=mode==='day'?(metric==='humidity'?[0,25,50,75,100]:metric==='temperature'?[0,10,20,30]:[0,250,500,750,1000]):metric==='humidity'?[55,60,65,70]:metric==='temperature'?[26,26.5,27,27.5,28]:[600,700,800,900];
 const start=rows[0]?.stamp??0,end=rows.at(-1)?.stamp??start+1,px=i=>mode==='day'?L+(i+.5)*(R-L)/rows.length:rows.length===1?(L+R)/2:L+(rows[i].stamp-start)/(end-start||1)*(R-L),py=v=>B-(v-domain[0])/(domain[1]-domain[0])*(B-T);
 const visible=mobile&&rows.length>6?[0,2,4,6]:rows.map((_,i)=>i),f=mobile?16:14,key=metric+'-'+mode+'-'+(mobile?'compact':'wide')+'-'+view;
 const days=[...new Set(rows.map(r=>r.date))],landmarks=mode==='hour'?days.slice(1).map(date=>({date,stamp:Date.parse(date+'T00:00:00+07:00')})):[],segments=[];
 for(let i=0;i<rows.length;i++)if(rows[i].value!==null){if(i&&rows[i-1].value!==null)segments.push(`<line x1="${px(i-1)}" y1="${py(rows[i-1].value)}" x2="${px(i)}" y2="${py(rows[i].value)}" stroke="#111" stroke-width="3"/>`);}
 const dayBands=days.map((date,i)=>{const left=i===0?L:L+(Date.parse(date+'T00:00:00+07:00')-start)/(end-start||1)*(R-L),right=i===days.length-1?R:L+(Date.parse(days[i+1]+'T00:00:00+07:00')-start)/(end-start||1)*(R-L),label=date.slice(8)+'/'+date.slice(5,7)+'/'+date.slice(0,4);return `<line x1="${left}" y1="244" x2="${right-3}" y2="244" stroke="#aaa"/><text class="chart-day-label" x="${(left+right)/2}" y="269" text-anchor="middle" font-size="${f}" font-weight="600">${label}</text>`;}).join('');
 let selected=s.point;if(!rows[selected]||rows[selected].value===null)selected=rows.map((r,i)=>r.value!==null?i:-1).filter(i=>i>=0).at(-1)??0;
 return `<svg class="chart pro-chart ${mobile?'chart-compact':'chart-wide'}" viewBox="0 0 ${W} ${H}" role="group" aria-label="${esc(m.label)} theo ${mode==='day'?'ngày':'giờ'}. Mốc thời gian UTC+7."><defs><pattern id="partial-${key}" width="8" height="8" patternUnits="userSpaceOnUse"><path d="M0 8L8 0" stroke="#fff" stroke-width="2"/></pattern></defs><text x="${L}" y="19" font-size="${f}">${esc(m.label)} (${m.unit})</text>${ticks.map(v=>`<line x1="${L}" y1="${py(v)}" x2="${R}" y2="${py(v)}" stroke="${v===0?'#999':'#ddd'}"/><text x="${L-10}" y="${py(v)+5}" text-anchor="end" font-size="${f}">${fmt(v)}</text>`).join('')}${landmarks.map(a=>{const x=L+(a.stamp-start)/(end-start||1)*(R-L);return `<line class="day-boundary" data-boundary="${a.date}" x1="${x}" y1="${T}" x2="${x}" y2="${B}" stroke="#888" stroke-dasharray="4 5"/><text x="${x+5}" y="38" font-size="${mobile?14:12}" font-weight="600">00:00</text>`;}).join('')}${rows.some(r=>r.value===null)?`<rect x="${px(rows.findIndex(r=>r.value===null))-8}" y="${T}" width="${R-px(rows.findIndex(r=>r.value===null))+8}" height="${B-T}" fill="#f4f4f4"/><text x="${R-5}" y="${T+28}" text-anchor="end" font-size="${f}">Chưa tới mốc</text>`:''}${mode==='hour'?segments.join(''):''}${rows.map((r,i)=>{if(r.value===null)return '';const x=px(i),y=py(r.value),active=i===selected,bw=Math.min(54,(R-L)/rows.length*.55),partial=mode==='day'&&r.date==='2026-11-03';return `<g data-point="${i}" data-label="${esc(r.label)}" data-value="${r.value}" data-unit="${m.unit}" data-metric="${esc(m.label)}" tabindex="0" role="button" aria-label="${esc(r.label)}: ${fmt(r.value)} ${m.unit}${partial?', chưa trọn ngày':''}">${mode==='day'?`<rect x="${x-bw/2}" y="${y}" width="${bw}" height="${B-y}" fill="${active?'#111':'#aaa'}"/>${partial?`<rect x="${x-bw/2}" y="${y}" width="${bw}" height="${B-y}" fill="url(#partial-${key})"/>`:''}`:`<circle cx="${x}" cy="${y}" r="${mobile?23:18}" fill="transparent"/><circle class="point" cx="${x}" cy="${y}" r="${active?6:4}" fill="#111" stroke="#fff" stroke-width="2"/>`}${(!mobile||active)?`<text class="point-value" x="${i===0?x+6:x}" y="${Math.max(31,y-13)}" text-anchor="${i===0?'start':'middle'}" font-size="${f}" font-weight="${active?700:500}">${fmt(r.value)}</text>`:''}</g>`;}).join('')}${visible.map(i=>`<text x="${px(i)}" y="223" text-anchor="${mode==='day'||mobile&&rows.length<=6?'middle':i===0?'start':i===rows.length-1?'end':'middle'}" font-size="${f}">${mode==='day'?rows[i].label:rows[i].time}</text>`).join('')}${mode==='hour'?dayBands:`<text x="${L}" y="265" font-size="${f}">Ngày / tháng · 2026</text><text x="${R}" y="265" font-size="${f}" text-anchor="end">03/11: chưa trọn ngày</text>`}</svg>`;
}

function dailyHorizontalSvg(rows,metric='humidity'){
 const m=metrics[metric],W=320,L=62,R=274,T=56,step=44,H=T+rows.length*step+22,maximum=metric==='humidity'?100:metric==='temperature'?30:1000,barTicks=metric==='humidity'?[0,25,50,75,100]:metric==='temperature'?[0,10,20,30]:[0,250,500,750,1000],px=v=>L+v/maximum*(R-L),key='horizontal-'+metric;
 return `<svg class="chart pro-chart chart-compact" viewBox="0 0 ${W} ${H}" role="group" aria-label="${m.label} trung bình theo ngày, thang bắt đầu từ 0"><defs><pattern id="${key}" width="8" height="8" patternUnits="userSpaceOnUse"><path d="M0 8L8 0" stroke="#fff" stroke-width="2"/></pattern></defs><text x="0" y="18" font-size="16">Ngày</text><text x="${R}" y="18" text-anchor="end" font-size="16">${m.unit}</text>${barTicks.map(v=>`<line x1="${px(v)}" y1="${T-14}" x2="${px(v)}" y2="${H-20}" stroke="#ddd"/><text x="${px(v)}" y="39" text-anchor="middle" font-size="15">${v}</text>`).join('')}${rows.map((r,i)=>{const y=T+i*step,partial=r.date==='2026-11-03';return `<g data-point="${i}" data-label="${r.label}" data-value="${r.value}" data-unit="${m.unit}" data-metric="${m.label}" tabindex="0" role="button" aria-label="${r.label}: ${fmt(r.value)} ${m.unit}${partial?', chưa trọn ngày':''}"><rect x="0" y="${y-6}" width="320" height="42" fill="transparent"/><text x="0" y="${y+20}" font-size="16">${r.label}</text><rect x="${L}" y="${y}" width="${px(r.value)-L}" height="28" fill="${i===s.point?'#111':'#aaa'}"/>${partial?`<rect x="${L}" y="${y}" width="${px(r.value)-L}" height="28" fill="url(#${key})"/>`:''}<text x="${px(r.value)+6}" y="${y+20}" font-size="16" font-weight="600">${fmt(r.value)}</text></g>`;}).join('')}</svg>`;
}

function chart(view='current'){
 const spec=chartSpec(view),m=metrics[spec.metric],v=spec.rows.filter(r=>r.value!==null).map(r=>r.value);
 if(!v.length)return '<p>Chưa có dữ liệu trong khoảng này.</p>';
 if(!spec.rows[s.point]||spec.rows[s.point].value===null)s.point=spec.rows.map((r,i)=>r.value!==null?i:-1).filter(i=>i>=0).at(-1);
 const selected=spec.rows[s.point],mean=v.reduce((a,b)=>a+b,0)/v.length;
 return `<div class="chart-wrap pro-chart-wrap"><div class="chart-summary"><span>Thấp nhất <strong>${fmt(Math.min(...v))}${m.unit}</strong></span><span>Trung bình <strong>${fmt(mean)}${m.unit}</strong></span><span>Cao nhất <strong>${fmt(Math.max(...v))}${m.unit}</strong></span></div>${chartSvg(spec)}${chartSvg(spec,true)}<div class="readout" id="chart-readout" aria-live="polite">${selected.label} · ${m.label}: <strong>${fmt(selected.value)} ${m.unit}</strong></div><p class="chart-footnote">${spec.mode==='day'?'Cột bắt đầu từ 0. Ngày 03/11 chưa kết thúc.':`Thang ${spec.metric==='humidity'?'55–70%':spec.metric==='temperature'?'26–28°C':'600–900 ppm'} để đọc biến động; đường không tô diện tích.`} · UTC+7</p><details class="chart-data"><summary>Xem các điểm đo</summary><div class="table-wrap"><table><caption class="sr-only">Bảng dữ liệu cho biểu đồ ${m.label}</caption><thead><tr><th>Thời điểm</th><th>${m.label} (${m.unit})</th></tr></thead><tbody>${spec.rows.map(r=>`<tr><td>${r.label}</td><td>${r.value===null?'Chưa tới mốc':fmt(r.value)}</td></tr>`).join('')}</tbody></table></div></details></div>`;
}

function overviewChart(){return chart('overview');}

function bars(){
 const spec=chartSpec('daily');
 return `<div class="bar-chart">${chartSvg({...spec,metric:'humidity',rows:sampleRows('humidity','day').map(r=>({...r,time:'00:00',stamp:Date.parse(r.date+'T00:00:00+07:00')}))})}${dailyHorizontalSvg(sampleRows('humidity','day'))}</div>`;
}

function heatmap(){
 const dates=['28/10','29/10','30/10','31/10','01/11','02/11','03/11'];
 return `<section class="card heatmap-section"><div class="row"><h2>Độ ẩm theo ngày và giờ (%)</h2><button data-route="daydetail">Chi tiết ngày →</button></div><p class="muted small">Mỗi hàng là một ngày, mỗi cột là một khung giờ. Đậm hơn là giá trị cao hơn.</p><p class="heat-scroll-hint">Vuốt ngang để xem đủ khung giờ khi màn hình hẹp.</p><div class="heatmap-scroll"><div class="heatmap" role="group" aria-label="Độ ẩm theo ngày và giờ"><span class="label">Ngày</span>${[0,4,8,12,16,20].map(h=>`<span class="label">${String(h).padStart(2,'0')}:00</span>`).join('')}${dates.map((date,c)=>`<span class="label heat-date">${date}</span>${heatValues.map((row,r)=>{const v=row[c];return `<button class="heat-cell" data-cell="${r},${c}" aria-pressed="${s.cell[0]===r&&s.cell[1]===c}" aria-label="${date} ${r*4}:00: ${v===null?'Chưa tới mốc':fmt(v)+' phần trăm'}" style="--color:${v===null?'#fafafa':`hsl(0 0% ${96-(v-60)*6}%)`}">${v===null?'—':''}</button>`;}).join('')}`).join('')}</div></div><div class="heat-scale">${[60,62.5,65,67.5,70].map(v=>`<span><i style="--color:hsl(0 0% ${96-(v-60)*6}%)"></i>${fmt(v)}%</span>`).join('')}</div><div class="readout" id="heat-readout" aria-live="polite">${heatReadout()}</div><p class="muted small">Ngày 03/11 lúc 16h và 20h chưa tới mốc · —: Chưa có dữ liệu. Dữ liệu minh họa.</p></section>`;
}

function section(route){return ['history','daily','daydetail','records','filters'].includes(route)?'history':['sensor','temperature','co2','device'].includes(route)?'sensor':route==='led'?'led':route==='overview'?'overview':'';}

function routeTitle(){return ({overview:'Giám sát',led:'Đèn LED',history:'Lịch sử',sensor:'Chi tiết độ ẩm',temperature:'Chi tiết nhiệt độ',co2:'CO₂ ước lượng',daily:'Phân tích theo ngày',daydetail:'Chi tiết ngày',records:'Bản ghi cảm biến',filters:'Bộ lọc thời gian',device:'Thiết bị & kết nối',telegram:'Kết nối Telegram','telegram-demo':'Hội thoại minh họa',profile:'Tài khoản',wifi:'Cấu hình WiFi'})[s.route]??'Smart Classroom';}

function recordRows(){return [...dateLabels.keys()].reverse().map(i=>({i,time:dateLabels[i],humidity:metrics.humidity.values[i],temperature:metrics.temperature.values[i],co2:metrics.co2.values[i]}));}

function recordTable(limit=7){return `<div class="table-wrap"><table class="records-table"><caption class="sr-only">Bản ghi cảm biến minh họa, UTC+7</caption><thead><tr><th>Thời điểm · UTC+7</th><th>Độ ẩm (%)</th><th>Nhiệt độ (°C)</th><th>CO₂ ước lượng (ppm)</th></tr></thead><tbody>${recordRows().slice(0,limit).map(r=>`<tr><td><strong>${r.time}</strong><small>2026 · Mẫu ${r.i+1}</small></td><td>${fmt(r.humidity)}</td><td>${fmt(r.temperature)}</td><td>${r.co2}</td></tr>`).join('')}</tbody></table></div>`;}

function featureHub(){return `<section class="feature-hub"><div class="row"><h2>Đi sâu vào phòng học</h2><span class="muted small">Cùng một dữ liệu, nhiều góc nhìn</span></div><div class="grid feature-grid">${[['temperature','01','Nhiệt độ','Đọc mốc đo, min/max và bản ghi.'],['co2','02','CO₂ ước lượng','Theo dõi xu hướng, kèm chú thích MQ-135.'],['records','03','Bản ghi cảm biến','Đối chiếu con số với biểu đồ.'],['daily','04','Phân tích theo ngày','So sánh ngày và xem từng khung giờ.'],['device','05','Thiết bị & kết nối','Kiểm tra dữ liệu mới, WiFi và hướng dẫn kết nối.'],['telegram','06','Telegram','Nhận cảnh báo độ ẩm, hỏi nhanh bằng lệnh.']].map(([r,i,t,d])=>`<button class="card feature-link" data-route="${r}"><span class="feature-index">${i}</span><strong>${t} <span aria-hidden="true">↗</span></strong><span>${d}</span></button>`).join('')}</div></section>`;}

function metricDetail(key){const m=metrics[key],v=m.values,mean=v.reduce((a,b)=>a+b)/v.length;return `<div class="subpage-actions"><button data-route="overview">← Tổng quan</button><button data-route="records">Xem bản ghi →</button></div>${!s.online?stale():''}<div class="grid detail-summary"><section class="card detail-hero"><p class="eyebrow">${m.label.toUpperCase()}</p><p class="detail-number">${fmt(v.at(-1))}<span>${m.unit}</span></p><p class="muted">03/11/2026 · 14:30 · ${s.online?'Lần nhận mới nhất':'Dữ liệu cũ'}</p></section><section class="card"><h2>Trong 24 giờ</h2><dl class="key-values"><div><dt>Thấp nhất</dt><dd>${fmt(Math.min(...v))} ${m.unit}</dd></div><div><dt>Trung bình mẫu</dt><dd>${fmt(mean)} ${m.unit}</dd></div><div><dt>Cao nhất</dt><dd>${fmt(Math.max(...v))} ${m.unit}</dd></div></dl></section></div><section class="card"><div class="row"><h2>${m.label} theo thời gian</h2><span class="small muted">7 mẫu · Cách nhau 4 giờ</span></div><p class="muted small">02/11/2026 14:30 → 03/11/2026 14:30</p>${chart(key)}${key==='co2'?'<p class="measurement-note">MQ-135 không chọn lọc riêng CO₂. Số liệu ước lượng để tham khảo; biểu đồ không phân loại mức an toàn.</p>':''}</section><section class="card records-preview"><h2>Ba mốc gần nhất</h2>${recordTable(3)}</section>`;}

function recordsPage(){return `<div class="subpage-actions"><button data-route="history">← Biểu đồ lịch sử</button><button data-route="filters">Chọn thời gian →</button></div><section class="card"><div class="row"><h2>Đối chiếu từng mốc đo</h2><span class="badge">7 bản ghi minh họa</span></div><p class="muted">02/11 14:30 → 03/11 14:30 · UTC+7</p>${recordTable()}<p class="measurement-note">Dữ liệu được lưu tự động kèm thời gian. Không cần thao tác lưu từng cảm biến.</p></section>`;}

function dailyPage(){return `<div class="subpage-actions"><button data-route="history">← Lịch sử theo giờ</button><button data-route="daydetail">Chi tiết 03/11 →</button></div><section class="card"><h2>${metrics[s.metric].label} trung bình theo ngày</h2><p class="muted">28/10–03/11/2026 · Ngày cuối chưa kết thúc</p>${chart('daily')}</section>${s.metric==='humidity'?heatmap():''}`;}

function dayDetailPage(){return `<div class="subpage-actions"><button data-route="daily">← Phân tích theo ngày</button><span class="badge">03/11/2026 · Chưa trọn ngày</span></div><section class="card"><h2>Độ ẩm theo khung 4 giờ</h2><p class="muted">Đang chọn 12:00 · 64,5% · Các khung 16h và 20h chưa tới mốc.</p>${chart('daydetail')}</section><section class="card records-preview"><h2>Đọc đúng phần còn thiếu</h2><p>Vùng xám và dấu — biểu thị mốc chưa có dữ liệu; đường không được nối qua phần này.</p><button data-route="records">Xem bản ghi thời điểm thực →</button></section>`;}

function filterPage(){const h=history(),filters=h.slice(0,h.indexOf('</section>')+10);return `<div class="subpage-actions"><button data-route="history">← Quay lại lịch sử</button></div><section class="page-description"><h2>Tìm đúng khoảng cần xem</h2><p class="muted">Chọn chỉ số và khoảng thời gian. Ngày tùy chọn cần áp dụng để đổi kết quả.</p></section>${filters}<button class="primary filter-done" data-route="history">Xem kết quả đã áp dụng →</button>`;}

function devicePage(){return `<div class="subpage-actions"><button data-route="overview">← Tổng quan</button><button data-route="telegram">Thông báo Telegram →</button></div><div class="grid device-layout"><section class="card"><p class="eyebrow">THIẾT BỊ PHÒNG HỌC</p><h2>ESP32 · Phòng học</h2><p class="device-status">${s.online?'● Có dữ liệu mới':'○ Chưa có bản tin mới'}</p><dl class="key-values"><div><dt>WiFi minh họa</dt><dd>Classroom-WiFi</dd></div><div><dt>Lần nhận gần nhất</dt><dd>03/11/2026 14:30</dd></div><div><dt>Cảm biến</dt><dd>DHT22 · MQ-135</dd></div><div><dt>Đèn</dt><dd>WS2812 · ${s.on?'Yêu cầu bật':'Yêu cầu tắt'}</dd></div></dl><button id="device-refresh">Kiểm tra lại dữ liệu</button><p id="device-result" class="small muted" role="status"></p></section><section class="card"><h2>Khi thiết bị chưa có dữ liệu</h2><ol class="setup-steps"><li><strong>Kiểm tra nguồn</strong><p>Đảm bảo thiết bị được cấp điện.</p></li><li><strong>Kiểm tra WiFi</strong><p>Thiết bị cần mạng WiFi đã cấu hình.</p></li><li><strong>Đổi mạng khi cần</strong><p>Giữ nút BOOT khoảng 5 giây rồi cấu hình lại bằng điện thoại.</p></li></ol><button data-route="wifi">Xem portal WiFi minh họa →</button><p class="measurement-note">Đã nhận cấu hình chưa đồng nghĩa đã online. Kiểm tra bản tin mới sau khi thiết bị khởi động lại.</p></section></div>`;}

function telegramPage(){return `<div class="subpage-actions"><button data-route="device">← Thiết bị & kết nối</button><button data-route="telegram-demo">Hội thoại mẫu →</button></div><div class="grid telegram-layout"><section class="card"><p class="eyebrow">THÔNG BÁO QUA TELEGRAM</p><h2>Một lần /start, nhận cảnh báo về sau</h2><ol class="setup-steps"><li><strong>Mở bot do nhóm cung cấp</strong><p>Nhận liên kết bot từ nhóm triển khai.</p></li><li><strong>Gửi /start trong Telegram</strong><p>Bot ghi nhận người nhận thông báo.</p></li><li><strong>Hỏi nhanh bằng lệnh</strong><p>/doam xem độ ẩm; /trangthai xem bình thường hay bất thường.</p></li></ol><button class="primary" data-route="telegram-demo">Xem hội thoại minh họa →</button></section><section class="card"><h2>Khi nào có cảnh báo?</h2><div class="threshold-pair"><div><strong>&lt; 30%</strong><span>Độ ẩm thấp</span></div><div><strong>&gt; 85%</strong><span>Độ ẩm cao</span></div></div><p>Đây là quy tắc của đồ án cho cảnh báo độ ẩm. Hệ thống có khoảng nghỉ giữa hai lần báo để tránh gửi liên tục.</p><p class="measurement-note">Telegram là kênh bên ngoài. Trang này hướng dẫn và mô phỏng, chưa gửi tin nhắn thật.</p></section></div>`;}

function telegramDemoPage(){const messages=s.telegramMessages??[{who:'bot',text:'Hội thoại mẫu. Hãy chọn /start để xem cách bot ghi nhận người nhận.'}];return `<div class="subpage-actions"><button data-route="telegram">← Hướng dẫn Telegram</button><span class="badge">Mô phỏng kênh bên ngoài</span></div><section class="card chat-demo"><h2>Smart Classroom Bot</h2><p class="muted small">Đây là hội thoại minh họa cho chức năng 6–7, không phải client Telegram thật.</p><div class="chat-log" role="log" aria-live="polite">${messages.map(x=>`<div class="chat-message ${x.who}"><span>${x.who==='bot'?'BOT':'BẠN'}</span><p>${esc(x.text)}</p></div>`).join('')}</div><div class="command-actions">${['/start','/doam','/trangthai'].map(c=>`<button data-command="${c}">${c}</button>`).join('')}</div><button id="telegram-alert-demo">Xem ví dụ cảnh báo độ ẩm 88%</button><p class="measurement-note">Ví dụ 88% là tình huống cảnh báo riêng; số đo hiện tại của bộ dữ liệu vẫn là 65%.</p></section>`;}

function profilePage(){return `<div class="subpage-actions"><button data-route="overview">← Tổng quan</button></div><section class="card profile-page"><p class="eyebrow">TÀI KHOẢN & PHIÊN</p><h2>${esc(s.user)}</h2><p class="muted">Một tài khoản cho web và điện thoại.</p><dl class="key-values"><div><dt>Trạng thái phiên</dt><dd>Đã đăng nhập</dd></div><div><dt>Phạm vi truy cập</dt><dd>Giám sát, lịch sử và điều khiển LED</dd></div></dl><div class="profile-links"><button data-route="device">Thiết bị & kết nối →</button><button data-route="telegram">Thông báo Telegram →</button></div><button class="danger" id="logout">Đăng xuất khỏi phiên này</button></section>`;}

function pageForRoute(){return ({overview,led,history,sensor,wifi,temperature:()=>metricDetail('temperature'),co2:()=>metricDetail('co2'),daily:dailyPage,daydetail:dayDetailPage,records:recordsPage,filters:filterPage,device:devicePage,telegram:telegramPage,'telegram-demo':telegramDemoPage,profile:profilePage}[s.route]??overview)();}

function bindChartPoints(){const select=el=>{s.point=+el.dataset.point;const readout=el.closest('.pro-chart-wrap')?.querySelector('#chart-readout');if(readout)readout.innerHTML=`${esc(el.dataset.label)} · ${esc(el.dataset.metric)}: <strong>${fmt(+el.dataset.value)} ${esc(el.dataset.unit)}</strong>`;el.closest('.pro-chart-wrap')?.querySelectorAll('.point').forEach(c=>c.setAttribute('r',c.parentElement.dataset.point===el.dataset.point?'6':'4'));};document.querySelectorAll('[data-point]').forEach(el=>{for(const type of ['click','focus','pointerenter'])el.addEventListener(type,()=>select(el));el.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();select(el);}if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const points=[...el.closest('svg').querySelectorAll('[data-point]')],i=points.indexOf(el),next=e.key==='Home'?0:e.key==='End'?points.length-1:Math.max(0,Math.min(points.length-1,i+(e.key==='ArrowRight'?1:-1)));points[next].focus();select(points[next]);}});});}

function bindExpanded(){document.querySelector('#device-refresh')?.addEventListener('click',()=>{document.querySelector('#device-result').textContent=s.online?'Dữ liệu minh họa mới nhất: 03/11/2026 14:30.':'Chưa có bản tin mới; kiểm tra nguồn và WiFi.';});document.querySelectorAll('[data-command]').forEach(b=>b.addEventListener('click',()=>{const cmd=b.dataset.command,reply=cmd==='/start'?'Đã ghi nhận người nhận (minh họa). Bot sẽ báo khi độ ẩm dưới 30% hoặc trên 85%.':cmd==='/doam'?'Độ ẩm mới nhất: 65% · 03/11/2026 14:30.':'Độ ẩm 65%: bình thường theo quy tắc 30–85% của đồ án.';s.telegramMessages=[...(s.telegramMessages??[]),{who:'user',text:cmd},{who:'bot',text:reply}];render();}));document.querySelector('#telegram-alert-demo')?.addEventListener('click',()=>{s.telegramMessages=[...(s.telegramMessages??[]),{who:'bot',text:'Ví dụ cảnh báo: Độ ẩm 88%, vượt ngưỡng 85%. Kiểm tra phòng học. Có khoảng nghỉ giữa hai lần báo.'}];render();});}

const routeNames=["overview","led","history","sensor","wifi","login","register","temperature","co2","records","daily","daydetail","filters","device","telegram","telegram-demo","profile"];
function bind(){bindExpanded();bindColorControls();const on=(sel,event,fn)=>document.querySelector(sel)?.addEventListener(event,fn);
document.querySelectorAll('[data-route]').forEach(el=>el.addEventListener('click',()=>navigate(el.dataset.route)));
for(const id of ['#account'])on(id,'click',e=>{accountOpener=e.currentTarget.id;s.account=true;render();document.querySelector('#account-close')?.focus();});
on('#account-close','click',()=>{s.account=false;render(accountOpener);});on('#account-backdrop','click',e=>{if(e.target.id==='account-backdrop'){s.account=false;render(accountOpener);}});on('#logout','click',()=>logout());
on('#power','click',()=>send('power'));on('#apply','click',()=>send('color'));
document.querySelectorAll('[data-color]').forEach(el=>el.addEventListener('click',()=>choose(el.dataset.color,el.id)));
on('.advanced','toggle',e=>{s.advanced=e.target.open;});on('#hex','input',e=>{s.hex=e.target.value;refreshDraft();});
on('#hex-preview','click',()=>{const hex=document.querySelector('#hex').value.trim().toUpperCase();s.hex=hex;if(!/^#[0-9A-F]{6}$/.test(hex)){s.hexError='Nhập # và 6 ký tự từ 0–9, A–F. Ví dụ: #EAB308.';render('hex');return;}choose(hex,'hex');});
on('#hex-cancel','click',()=>{s.brightness=s.appliedBrightness;choose(s.applied,'hex');s.advanced=false;render();});
on('#metric','change',e=>{s.metric=e.target.value;s.point=6;loadHistory();});
on('#range','change',e=>{s.range=e.target.value;s.dateError='';if(s.range==='custom'){s.dirty=true;render('from');}else{s.appliedRange=s.range;s.mode=s.range==='7d'?'day':'hour';s.dirty=false;loadHistory();}});
document.querySelectorAll('[data-mode]').forEach(el=>el.addEventListener('click',()=>{s.mode=el.dataset.mode;s.point=6;loadHistory();}));
for(const id of ['from','to'])on('#'+id,'change',e=>{s[id]=e.target.value;s.dirty=true;s.dateError='';render(id);});
on('#apply-dates','click',()=>{s.from=document.querySelector('#from').value;s.to=document.querySelector('#to').value;if(!s.from||!s.to||s.from>s.to){s.dateError='Chọn đủ hai ngày; Từ ngày không được sau Đến ngày.';render('from');return;}s.appliedFrom=s.from;s.appliedTo=s.to;s.appliedRange='custom';s.dirty=false;s.dateError='';if(s.route==='filters'){s.route='history';location.hash='history';}loadHistory();});
bindChartPoints();
document.querySelectorAll('[data-cell]').forEach(el=>el.addEventListener('click',()=>{s.cell=el.dataset.cell.split(',').map(Number);document.querySelectorAll('[data-cell]').forEach(b=>b.setAttribute('aria-pressed',b===el));document.querySelector('#heat-readout').innerHTML=heatReadout();}));
on('#reset-range','click',()=>{s.range=s.appliedRange='24h';s.mode='hour';s.dirty=false;loadHistory();});on('#retry-history','click',loadHistory);
on('#test-online','click',()=>{s.online=!s.online;s.feedback=null;render();});on('#test-fail','click',()=>{s.failNext=!s.failNext;render();});on('#test-expire','click',()=>logout(true));
document.querySelectorAll('[data-history-state]').forEach(el=>el.addEventListener('click',()=>{s.route='history';s.historyState=el.dataset.historyState;render();}));
on('#auth-switch','click',()=>{s.route=s.route==='register'?'login':'register';s.authMessage='';render();});
on('#show-password','click',e=>{const p=document.querySelector('#password'),show=p.type==='password';p.type=show?'text':'password';e.target.textContent=show?'Ẩn':'Hiện';e.target.setAttribute('aria-pressed',show);});
on('#demo-login','click',()=>{document.querySelector('#username').value='demo_user';document.querySelector('#password').value='smartclassroom16';document.querySelector('#auth-form').requestSubmit();});
on('#auth-form','submit',async e=>{e.preventDefault();const u=document.querySelector('#username').value.trim(),p=document.querySelector('#password').value,reg=s.route==='register',c=document.querySelector('#confirm')?.value,err=document.querySelector('#auth-error'),button=document.querySelector('#auth-submit');let message='';if(!u||!p)message='Nhập tài khoản và mật khẩu.';else if(reg&&p.length<8)message='Mật khẩu cần tối thiểu 8 ký tự.';else if(reg&&p!==c)message='Mật khẩu xác nhận chưa trùng.';else if(reg&&users.has(u))message='Tên tài khoản đã tồn tại.';else if(!reg&&users.get(u)!==p)message='Tài khoản hoặc mật khẩu không đúng.';if(message){err.textContent=message;document.querySelector('#username').setAttribute('aria-invalid','true');return;}button.disabled=true;button.textContent='Đang xử lý…';await new Promise(r=>setTimeout(r,400));if(reg){users.set(u,p);s.newUser=u;s.authMessage='Đăng ký thành công. Hãy đăng nhập để tiếp tục.';s.route='login';render();}else{s.user=u;s.authMessage='';s.route='overview';s.session++;location.hash='overview';render();}});
on('#wifi-form','submit',e=>{e.preventDefault();document.querySelector('#wifi-result').textContent='Đã nhận cấu hình (minh họa). Thiết bị sẽ khởi động lại; trở về mạng thường dùng rồi kiểm tra dữ liệu.';});
}
document.addEventListener('keydown',e=>{if(!s.account)return;if(e.key==='Escape'){s.account=false;render(accountOpener);}if(e.key==='Tab'){const a=[...document.querySelectorAll('.dialog button')],first=a[0],last=a.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{const route=location.hash.slice(1);if(!s.user&&!['login','register','wifi'].includes(route)){s.route='login';location.hash='login';render();return;}if(routeNames.includes(route)&&route!==s.route){s.route=route;render();}});
const initial=new URLSearchParams(location.search);if(initial.has('route'))s.route=initial.get('route');else if(location.hash)s.route=location.hash.slice(1);if(initial.get('offline')==='1')s.online=false;if(s.route==='expired'){s.route='login';s.user=null;s.authMessage='Phiên đã hết. Vui lòng đăng nhập lại.';}if(['login','register'].includes(s.route))s.user=null;
render();
})();
